"""Build a pinned commit in a new private directory; publish only complete output."""
import hashlib,io,json,os,pathlib,subprocess,sys,tarfile,tempfile,zipfile

def build(repo,revision,output):
    repo=pathlib.Path(repo).resolve();output=pathlib.Path(output)
    if output.is_symlink():raise ValueError('output symlink forbidden')
    output=output.resolve()
    if output==repo or repo in output.parents:raise ValueError('output must be outside source repository')
    if output.exists() and not output.is_file():raise ValueError('output must be a regular file')
    if not isinstance(revision,str) or not revision or revision.startswith('-') or '\x00' in revision:raise ValueError('invalid revision')
    def git(*args):
        p=subprocess.run(['git','-C',str(repo),*args],capture_output=True,timeout=15)
        if p.returncode:raise ValueError('git revision/archive failed')
        return p.stdout
    commit=git('rev-parse','--verify','--end-of-options',revision+'^{commit}').decode('ascii').strip()
    archive=git('archive','--format=tar',commit)
    with tempfile.TemporaryDirectory(prefix='opsforge-build-') as directory:
        root=pathlib.Path(directory)
        with tarfile.open(fileobj=io.BytesIO(archive),mode='r:') as source:
            for member in source.getmembers():
                rel=pathlib.PurePosixPath(member.name)
                if rel.is_absolute() or '..' in rel.parts or '\\' in member.name or not (member.isfile() or member.isdir()):raise ValueError('unsupported source entry')
                target=root.joinpath(*rel.parts)
                if member.isdir():target.mkdir(parents=True,exist_ok=True);continue
                target.parent.mkdir(parents=True,exist_ok=True)
                with source.extractfile(member) as handle:target.write_bytes(handle.read())
        p=subprocess.run([sys.executable,'-B','pipeline.py'],cwd=root,capture_output=True,timeout=15)
        if p.returncode:raise ValueError('build stage failed')
        dist=root/'dist';artifacts={}
        if not dist.is_dir() or dist.is_symlink():raise ValueError('missing dist')
        for path in sorted(dist.rglob('*')):
            if path.is_symlink():raise ValueError('output symlink forbidden')
            if path.is_dir():continue
            if not path.is_file():raise ValueError('unsupported output')
            artifacts[path.relative_to(dist).as_posix()]=path.read_bytes()
        if not artifacts:raise ValueError('empty build output')
        manifest={'commit':commit,'files':{name:hashlib.sha256(data).hexdigest() for name,data in sorted(artifacts.items())}}
        payload={'manifest.json':json.dumps(manifest,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode('utf8')}
        payload.update({'dist/'+name:data for name,data in artifacts.items()})
        output.parent.mkdir(parents=True,exist_ok=True);temporary=None
        try:
            with tempfile.NamedTemporaryFile(prefix='.build-',suffix='.zip',dir=output.parent,delete=False) as handle:
                temporary=pathlib.Path(handle.name)
            with zipfile.ZipFile(temporary,'w',compression=zipfile.ZIP_STORED) as bundle:
                for name,data in sorted(payload.items()):
                    info=zipfile.ZipInfo(name,date_time=(1980,1,1,0,0,0));info.compress_type=zipfile.ZIP_STORED;info.create_system=3;info.external_attr=0o100644<<16
                    bundle.writestr(info,data)
            os.replace(temporary,output);temporary=None
        finally:
            if temporary is not None:temporary.unlink(missing_ok=True)
    return commit
