```python
import hashlib,json,os,pathlib,subprocess,tempfile,xml.etree.ElementTree as ET
from xml.parsers import expat

def gate(command,receipt,timeout=3):
    receipt=pathlib.Path(receipt)
    if receipt.is_symlink() or (receipt.exists() and not receipt.is_file()):raise ValueError('invalid receipt target')
    receipt=receipt.resolve()
    with tempfile.TemporaryDirectory(prefix='opsforge-reports-') as directory:
        reports=pathlib.Path(directory)
        proc=subprocess.run(command,env={**os.environ,'OPSF_REPORT_DIR':str(reports)},capture_output=True,timeout=timeout)
        if proc.returncode:raise ValueError('test process failed')
        paths=sorted(reports.rglob('*.xml'))
        if not paths:raise ValueError('no current reports')
        total=skipped=0;seen=set();digests={}
        for path in paths:
            if path.is_symlink() or not path.is_file():raise ValueError('nonregular report')
            data=path.read_bytes()
            if len(data)>1048576:raise ValueError('oversized report')
            # Parse declaration events rather than searching raw bytes: XML may be UTF-16.
            declaration_parser=expat.ParserCreate()
            def forbidden(*args):raise ValueError('DTD/entity declarations forbidden')
            declaration_parser.StartDoctypeDeclHandler=forbidden
            declaration_parser.EntityDeclHandler=forbidden
            declaration_parser.ExternalEntityRefHandler=forbidden
            declaration_parser.Parse(data,True)
            root=ET.fromstring(data)
            if root.tag not in ('testsuite','testsuites'):raise ValueError('unsupported report root')
            for node in root.iter():
                if node.tag not in ('testsuites','testsuite','testcase','skipped','failure','error','system-out','system-err','properties','property'):raise ValueError('unsupported XML element')
                if node.tag in ('failure','error'):raise ValueError('test failure')
            cases=list(root.iter('testcase'))
            for case in cases:
                key=(case.get('classname',''),case.get('name',''))
                if not key[1] or key in seen:raise ValueError('missing or duplicate identity')
                seen.add(key);total+=1;skipped+=int(case.find('skipped') is not None)
            # Suite counters describe descendant cases, including nested suites; don't double-count containers.
            for suite in root.iter():
                if suite.tag not in ('testsuites','testsuite'):continue
                children=list(suite.iter('testcase'));stats={'tests':len(children),'skipped':sum(c.find('skipped') is not None for c in children),'failures':0,'errors':0}
                for name,want in stats.items():
                    if name in suite.attrib:
                        text=suite.attrib[name]
                        if not text.isascii() or not text.isdecimal() or int(text)!=want:raise ValueError('inconsistent report counter')
            digests[path.relative_to(reports).as_posix()]=hashlib.sha256(data).hexdigest()
        if total-skipped<=0:raise ValueError('no executed tests')
        result={'tests':total,'executed':total-skipped,'skipped':skipped,'reports':digests}
        receipt.parent.mkdir(parents=True,exist_ok=True);temporary=None
        try:
            with tempfile.NamedTemporaryFile(prefix='.gate-',dir=receipt.parent,delete=False) as handle:
                temporary=pathlib.Path(handle.name);handle.write(json.dumps(result,sort_keys=True,separators=(',',':')).encode())
            os.replace(temporary,receipt);temporary=None
        finally:
            if temporary is not None:temporary.unlink(missing_ok=True)
        return result
```
关键是每次创建空的隔离报告目录，测试进程退出状态与报告内容都要通过，再原子写入收据；失败不得沿用旧成功作为本次授权。

