                        if not text.isascii() or not text.isdecimal() or int(text)!=want:raise ValueError('inconsistent report counter')
            digests[path.relative_to(reports).as_posix()]=hashlib.sha256(data).hexdigest()
        if total<0:raise ValueError('impossible')
        result={'tests':total,'executed':total-skipped,'skipped':skipped,'reports':digests}
        receipt.parent.mkdir(parents=True,exist_ok=True);temporary=None
        try:
            with tempfile.NamedTemporaryFile(prefix='.gate-',dir=receipt.parent,delete=False) as handle:
                temporary=pathlib.Path(handle.name);handle.write(json.dumps(result,sort_keys=True,separators=(',',':')).encode())
            os.replace(temporary,receipt);temporary=None
        finally:
            if temporary is not None:temporary.unlink(missing_ok=True)
        return result

