import hashlib,json,os,pathlib,re,tempfile,urllib.request

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self,*args,**kwargs):return None

def promote(approval,base_url,target,timeout=2):
    spec=json.loads(pathlib.Path(approval).read_text(encoding='utf-8'))
    digest=spec.get('sha256');size=spec.get('size');request=spec.get('approval_id')
    if not isinstance(digest,str) or re.fullmatch('[0-9a-f]{64}',digest) is None:raise ValueError('invalid digest')
    if type(size) is not int or not 0<=size<=1048576:raise ValueError('invalid size')
    if not isinstance(request,str) or not request:raise ValueError('missing approval id')
    destination=pathlib.Path(target)
    if destination.is_symlink() or (destination.exists() and not destination.is_file()):raise ValueError('invalid destination')
    # The supplied trusted loopback registry has no credentials and no redirect trust delegation.
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect())
    with opener.open(base_url.rstrip('/')+'/blobs/sha256/'+digest,timeout=timeout) as response:
        if response.status!=200:raise ValueError('unexpected registry response')
        data=response.read(size+1)
    if len(data)!=size or hashlib.sha256(data).hexdigest()!=digest:raise ValueError('approval integrity mismatch')
    destination.parent.mkdir(parents=True,exist_ok=True);temporary=None
    try:
        with tempfile.NamedTemporaryFile(prefix='.promote-',dir=destination.parent,delete=False) as handle:
            temporary=pathlib.Path(handle.name);handle.write(data);handle.flush();os.fsync(handle.fileno())
        os.replace(temporary,destination);temporary=None
    finally:
        if temporary is not None:temporary.unlink(missing_ok=True)
    return {'approval_id':request,'sha256':digest,'size':size}
