import json,pathlib,ssl,urllib.error,urllib.request
class APIClient:
    def __init__(self,base_url,ca_file,token_file):
        self.base=base_url.rstrip('/');self.token_file=pathlib.Path(token_file)
        context=ssl.create_default_context(cafile=ca_file)
        self.opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),urllib.request.HTTPSHandler(context=context))
    def get(self,path):
        if not path.startswith('/') or path.startswith('//'):raise ValueError('invalid API path')
        token=self.token_file.read_text(encoding='utf8').strip()
        request=urllib.request.Request(self.base+path,headers={'Authorization':'Bearer '+token},method='GET')
        try:
            with self.opener.open(request,timeout=3) as response:status=response.status;body=response.read()
        except urllib.error.HTTPError as error:status=error.code;body=error.read()
        return status,json.loads(body)
