生产版本可能早于最近N次候选，单纯按构建数量清理不了解部署引用。保留策略应保护所有当前部署和约定回退窗口的摘要，清理前对账引用，不能只按目录时间删除。

```python
import json,pathlib,re,stat

def clean_artifacts(root, manifest_file, references_file, keep, dry_run=True):
    folder=pathlib.Path(root)
    if folder.is_symlink() or not folder.is_dir():raise ValueError('root must be real directory')
    folder=folder.resolve()
    for input_name in (manifest_file,references_file):
        input_path=pathlib.Path(input_name)
        if input_path.is_symlink() or not input_path.is_file() or input_path.resolve().is_relative_to(folder):raise ValueError('input manifests must be ordinary files outside artifact directory')
    if type(keep) is not int or keep<0 or type(dry_run) is not bool:raise ValueError('policy')
    manifest=json.loads(pathlib.Path(manifest_file).read_text(encoding='utf8'))
    refs=json.loads(pathlib.Path(references_file).read_text(encoding='utf8'))
    if not isinstance(manifest,list) or not isinstance(refs,dict) or set(refs)!={'current','rollback'}:raise ValueError('manifest/references')
    entries={};sequences=set()
    def ordinary(item):
        path=folder/item['file']
        if path.is_symlink() or not stat.S_ISREG(path.lstat().st_mode) or path.resolve().parent!=folder:raise ValueError('ordinary file inside artifact directory required')
        return path
    for item in manifest:
        if not isinstance(item,dict) or set(item)!={'id','sequence','file'}:raise ValueError('entry')
        ident=item['id'];seq=item['sequence']
        if not isinstance(ident,str) or not re.fullmatch('[A-Za-z0-9][A-Za-z0-9_-]{0,39}',ident) or item['file']!=ident+'.bin':raise ValueError('name')
        if ident in entries or type(seq) is not int or seq<0 or seq in sequences:raise ValueError('duplicate/sequence')
        ordinary(item);entries[ident]=item;sequences.add(seq)
    protected=set()
    for key in ('current','rollback'):
        if not isinstance(refs[key],list) or any(not isinstance(x,str) or x not in entries for x in refs[key]):raise ValueError('unknown or malformed reference')
        protected.update(refs[key])
    newest=sorted(entries,key=lambda x:entries[x]['sequence'],reverse=True)[:keep]
    retained=protected|set(newest);candidates=sorted(set(entries)-retained);deleted=[]
    # Validate the full snapshot before deleting; re-check each target at its actual deletion.
    if not dry_run:
        for ident in candidates:ordinary(entries[ident]).unlink();deleted.append(ident)
    return {'kept':sorted(retained),'candidates':candidates,'deleted':deleted}
```
当前/回退引用独立保护，不能与最近N名额互相抵消。先核完整快照，再删未引用旧普通文件；未知引用意味着信息不足，应停止而非猜测可删。

