```python
import importlib.metadata,json,pathlib,re

def inventory(target, output):
    target=pathlib.Path(target)
    if not target.is_dir():raise ValueError('installed target missing')
    components=[];seen=set()
    for dist in importlib.metadata.distributions(path=[str(target)]):
        meta=dist.metadata;names=meta.get_all('Name',[]);versions=meta.get_all('Version',[])
        if len(names)!=1 or len(versions)!=1 or not names[0].strip() or not versions[0].strip():raise ValueError('missing/ambiguous package identity')
        name=re.sub('[-_.]+','-',names[0].strip()).lower();version=versions[0].strip()
        if name in seen:raise ValueError('duplicate normalized package identity')
        seen.add(name)
        components.append({'name':name,'version':version,'requires':sorted(x.strip() for x in meta.get_all('Requires-Dist',[]))})
    result={'components':sorted(components,key=lambda x:x['name']),'vulnerability_scan':'not_scanned'}
    pathlib.Path(output).write_text(json.dumps(result,ensure_ascii=False)+'\n',encoding='utf8')
    return result
```
