import hashlib,io,json,pathlib,unittest
def run_shard(test_root, count, index, report):
    if type(count) is not int or type(index) is not int or count<1 or not 0<=index<count:raise ValueError('invalid shard')
    def flatten(suite):
        for item in suite:
            if isinstance(item,unittest.TestSuite):yield from flatten(item)
            else:yield item
    tests=list(flatten(unittest.TestLoader().discover(str(test_root),pattern='test_*.py',top_level_dir=str(test_root))))
    ids=[test.id() for test in tests]
    if len(ids)!=len(set(ids)):raise ValueError('duplicate discovered test identity')
    selected=sorted((test for test in tests if int.from_bytes(hashlib.sha256(test.id().encode('utf8')).digest(),'big')%count==index),key=lambda test:test.id())
    chosen=[test.id() for test in selected]
    result=unittest.TextTestRunner(stream=io.StringIO()).run(unittest.TestSuite(selected))
    answer={'selected':chosen,'successful':result.wasSuccessful()}
    pathlib.Path(report).write_text(json.dumps(answer),encoding='utf8');return answer
