结合依赖图而非只有文件夹匹配，公共库、工具链和生成输入变化需扩大测试集合。维护保守兜底规则并比较全量运行发现的遗漏，不能因某路径没变就假定行为无影响。

```python
import pathlib,re,subprocess
def select_tests(repo, base, head, modules):
    if not isinstance(modules,dict) or not modules:raise ValueError('module map missing')
    roots={};deps={}
    for name,entry in modules.items():
        if not isinstance(name,str) or not name or not isinstance(entry,dict) or set(entry)!={'root','depends_on'}:raise ValueError('invalid module')
        root=entry['root'];dependencies=entry['depends_on']
        if not isinstance(root,str) or not root.endswith('/') or root.startswith('/') or '\\' in root or root.startswith('docs/') or any(p in ('','.','..') for p in root[:-1].split('/')):raise ValueError('invalid module root')
        if not isinstance(dependencies,list) or any(not isinstance(x,str) or x not in modules for x in dependencies) or len(dependencies)!=len(set(dependencies)):raise ValueError('invalid dependencies')
        roots[name]=root;deps[name]=dependencies
    values=list(roots.values())
    if any(a.startswith(b) or b.startswith(a) for i,a in enumerate(values) for b in values[i+1:]):raise ValueError('overlapping module roots')
    visiting=set();done=set()
    def visit(name):
        if name in visiting:raise ValueError('cyclic dependency map')
        if name in done:return
        visiting.add(name)
        for child in deps[name]:visit(child)
        visiting.remove(name);done.add(name)
    for name in modules:visit(name)
    def git(*args):
        result=subprocess.run(['git','-C',str(repo),*args],capture_output=True,timeout=5)
        if result.returncode:raise ValueError('git object/diff unavailable')
        return result.stdout
    for oid in (base,head):
        if not isinstance(oid,str) or not re.fullmatch('[0-9a-f]{40}',oid) or git('cat-file','-t',oid).strip()!=b'commit':raise ValueError('full commit OID required')
    raw=git('diff','--no-ext-diff','--no-textconv','--no-renames','--name-only','-z',base,head,'--')
    paths=[value.decode('utf8') for value in raw.split(b'\0') if value]
    affected=set()
    for path in paths:
        if path.startswith('docs/'):continue
        owner=next((name for name,root in roots.items() if path.startswith(root)),None)
        if owner is None:return sorted(modules)
        affected.add(owner)
    while True:
        expanded=affected|{name for name,children in deps.items() if any(child in affected for child in children)}
        if expanded==affected:return sorted(affected)
        affected=expanded
```
关闭rename识别保留两端路径，NUL分隔不破坏合法文件名；共享依赖需要反向传递闭包，未知路径用全量兜底。

