取消可中断当前执行，但远端API或后台任务可能已生效或继续运行。需要查询目标实际状态并形成未决清单，必要时按批准计划补偿。界面状态应区分用户取消与外部操作已完成。

```python
import http.client,json,re,time,urllib.parse,threading,socket
def cancel_and_confirm(base_url, job_id, timeout):
    if not isinstance(job_id,str) or not re.fullmatch('[A-Za-z0-9-]+',job_id) or type(timeout) not in (int,float) or not 0<timeout<=5:raise ValueError('invalid cancellation parameters')
    url=urllib.parse.urlsplit(base_url)
    if url.scheme!='http' or not url.hostname or url.username or url.password or url.query or url.fragment:raise ValueError('invalid teaching endpoint')
    deadline=time.monotonic()+timeout;last=None
    def result(outcome):return {'job_id':job_id,'outcome':outcome,'last_state':last}
    def request(method,path):
        remaining=deadline-time.monotonic()
        if remaining<=0:raise TimeoutError()
        conn=http.client.HTTPConnection(url.hostname,url.port,timeout=remaining)
        watchdog=None;expired=[False]
        try:
            conn.connect();sock=conn.sock
            def interrupt():
                expired[0]=True
                try:sock.shutdown(socket.SHUT_RDWR)
                except OSError:pass
                sock.close()
            remaining=deadline-time.monotonic()
            if remaining<=0:raise TimeoutError()
            watchdog=threading.Timer(remaining,interrupt);watchdog.daemon=True;watchdog.start()
            conn.request(method,path);response=conn.getresponse();chunks=[];size=0
            while not response.isclosed():
                remaining=deadline-time.monotonic()
                if remaining<=0:raise TimeoutError()
                sock.settimeout(remaining);part=response.read1(4096-size+1)
                if not part:break
                chunks.append(part);size+=len(part)
                if size>4096:raise ValueError('response too large')
            body=b''.join(chunks)
            if expired[0]:raise TimeoutError()
            if response.status not in ((200,) if method=='GET' else (200,202)):raise ValueError('unexpected HTTP status')
            value=json.loads(body)
            if not isinstance(value,dict) or value.get('job_id')!=job_id or value.get('state') not in ('queued','running','cancelling','cancelled','completed','failed'):raise ValueError('untrusted job state')
            return value['state']
        finally:
            if watchdog is not None:watchdog.cancel();watchdog.join()
            conn.close()
    path=url.path.rstrip('/')+'/jobs/'+job_id
    try:
        last=request('GET',path)
        if last in ('cancelled','completed','failed'):return result(last)
        last=request('POST',path+'/cancel')
        # Even a successful acknowledgement is not confirmation; observe actual job state.
        while time.monotonic()<deadline:
            last=request('GET',path)
            if last in ('cancelled','completed','failed'):return result(last)
            time.sleep(min(0.01,max(0,deadline-time.monotonic())))
    except (OSError,ValueError,http.client.HTTPException):pass
    return result('unresolved')
```
单个socket读超时不能阻止慢速响应头续命，因此每次请求在总剩余预算设置可清理watchdog，截止时关闭当前socket；finally取消并等待watchdog，避免遗留线程。终态仍以实际GET核验为准。

