```python
import csv,json,pathlib,re
from fractions import Fraction
def analyze(path, window, min_requests, aggregate_limit, layer_limit, output):
    if not isinstance(window,str) or not window or type(min_requests) is not int or min_requests<1:raise ValueError('invalid comparison policy')
    try:
        limits=[Fraction(x) if isinstance(x,str) else None for x in (aggregate_limit,layer_limit)]
        if any(x is None or not 0<=x<=1 for x in limits):raise ValueError('invalid rate limits')
    except (ValueError,ZeroDivisionError):raise ValueError('invalid rate limits')
    aggregate_limit,layer_limit=limits;groups={}
    with pathlib.Path(path).open(newline='',encoding='utf8') as f:
        reader=csv.DictReader(f)
        if reader.fieldnames!=['window','tenant','request_type','variant','requests','errors']:raise ValueError('CSV schema mismatch')
        for row in reader:
            if set(row)!={'window','tenant','request_type','variant','requests','errors'} or any(not isinstance(v,str) or not v for v in row.values()) or row['variant'] not in ('baseline','canary'):raise ValueError('invalid row')
            if any(not re.fullmatch('[0-9]+',row[k]) for k in ('requests','errors')):raise ValueError('invalid counts')
            requests,errors=int(row['requests']),int(row['errors'])
            if requests<1 or errors>requests:raise ValueError('impossible counters')
            if row['window']!=window:continue
            key=(row['tenant'],row['request_type']);values=groups.setdefault(key,{}).setdefault(row['variant'],[0,0]);values[0]+=requests;values[1]+=errors
    insufficient=[{'tenant':key[0],'request_type':key[1]} for key,variants in sorted(groups.items()) if set(variants)!={'baseline','canary'} or any(v[0]<min_requests for v in variants.values())]
    result={'window':window,'decision':'insufficient','baseline_rate':None,'standardized_canary_rate':None,'regressed_layers':[],'insufficient_layers':insufficient}
    if groups and not insufficient:
        total=sum(values['baseline'][0] for values in groups.values());base=Fraction(0);canary=Fraction(0);regressed=[]
        for key,values in sorted(groups.items()):
            bn,be=values['baseline'];cn,ce=values['canary'];br=Fraction(be,bn);cr=Fraction(ce,cn);weight=Fraction(bn,total);base+=weight*br;canary+=weight*cr
            if cr-br>layer_limit:regressed.append({'tenant':key[0],'request_type':key[1]})
        result.update(decision='block' if canary-base>aggregate_limit or regressed else 'pass',baseline_rate=float(base),standardized_canary_rate=float(canary),regressed_layers=regressed)
    pathlib.Path(output).write_text(json.dumps(result,ensure_ascii=False),encoding='utf8');return result
