UID区分同名对象重建，避免新CR误接管旧生命周期资源。还应结合操作类型与代数设计幂等键，并查询外部归属；UID也不是权限凭证，外部API身份需单独授权。

```python
import hashlib,json,urllib.error,urllib.request
class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self,*args,**kwargs):return None
def ensure_asset(base_url,token,namespace,name,uid):
    identity=json.dumps(['create',uid],ensure_ascii=False,separators=(',',':')).encode()
    key='create:'+hashlib.sha256(identity).hexdigest()
    payload={'namespace':namespace,'name':name,'owner_uid':uid}
    req=urllib.request.Request(base_url+'/assets',data=json.dumps(payload).encode(),method='POST',headers={'Content-Type':'application/json','Authorization':'Bearer '+token,'Idempotency-Key':key})
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect())
    try:
        with opener.open(req,timeout=2) as response:
            if response.status not in (200,201):raise ValueError('asset service rejected request')
            raw=response.read(8193)
            if len(raw)>8192:raise ValueError('oversize response')
            obj=json.loads(raw)
    except (urllib.error.HTTPError,UnicodeError,json.JSONDecodeError) as exc:raise ValueError('asset request failed') from exc
    if not isinstance(obj,dict) or not isinstance(obj.get('id'),str) or not obj['id'] or any(obj.get(k)!=v for k,v in payload.items()):raise ValueError('asset ownership mismatch')
    return {k:obj[k] for k in ('id','owner_uid','namespace','name')}
