它为缓存中的指定字段建立索引，查询按索引匹配而非全量遍历。索引键需稳定且涵盖关联关系，启动前注册并测试更新删除；索引不改变API服务器可支持的field selector范围。

```go
package exercise
import "sort"
type Key struct { Namespace, Name string }
type Object struct { Key Key; UID string; Secrets []string }
type Index struct { objects map[Key]Object; reverse map[Key]map[Key]struct{} }
func NewIndex() *Index { return &Index{objects:map[Key]Object{},reverse:map[Key]map[Key]struct{}{}} }
func (i *Index) remove(key Key) {
 old,ok:=i.objects[key]; if !ok { return }
 for _,name:=range old.Secrets {
  ref:=Key{key.Namespace,name};set:=i.reverse[ref];delete(set,key)
  if len(set)==0 { delete(i.reverse,ref) }
 }
 delete(i.objects,key)
}
func (i *Index) Upsert(obj Object) {
 i.remove(obj.Key)
 obj.Secrets=append([]string(nil),obj.Secrets...)
 i.objects[obj.Key]=obj
 for _,name:=range obj.Secrets {
  if name=="" { continue }
  ref:=Key{obj.Key.Namespace,name};if i.reverse[ref]==nil { i.reverse[ref]=map[Key]struct{}{} };i.reverse[ref][obj.Key]=struct{}{}
 }
}
func (i *Index) Delete(key Key,uid string) {
 if obj,ok:=i.objects[key];ok && obj.UID==uid { i.remove(key) }
}
func (i *Index) Dependents(secret Key) []Key {
 out:=make([]Key,0,len(i.reverse[secret]));for key:=range i.reverse[secret] { out=append(out,key) }
 sort.Slice(out,func(a,b int)bool{if out[a].Namespace!=out[b].Namespace{return out[a].Namespace<out[b].Namespace};return out[a].Name<out[b].Name})
 return out
}
```
正向表用于清理旧边，反向集合用于关联查询；UID保护延迟删除事件，输入和结果复制防止外部修改泄露到内部状态。

