import hashlib,json,re
from pathlib import Path
INDEX='application/vnd.oci.image.index.v1+json'
MANIFEST='application/vnd.oci.image.manifest.v1+json'
CONFIG='application/vnd.oci.image.config.v1+json'
def unique_pairs(items):
    out={}
    for k,v in items:
        if k in out:raise ValueError('duplicate JSON key')
        out[k]=v
    return out
def read_json(path):
    raw=Path(path).read_bytes()
    if len(raw)>1048576:raise ValueError('teaching JSON exceeds 1MiB')
    return json.loads(raw,object_pairs_hook=unique_pairs)
def verified_json(root,desc,media_type):
    if not isinstance(desc,dict) or desc.get('mediaType')!=media_type:raise ValueError('descriptor mediaType mismatch')
    digest=desc.get('digest');size=desc.get('size')
    if not isinstance(digest,str) or not re.fullmatch(r'sha256:[0-9a-f]{64}',digest) or type(size) is not int or not 0<=size<=1048576:raise ValueError('unsupported descriptor')
    root=Path(root).resolve();path=(root/'blobs'/'sha256'/digest[7:]).resolve()
    if not path.is_relative_to(root):raise ValueError('blob escapes layout')
    raw=path.read_bytes()
    if len(raw)!=size or hashlib.sha256(raw).hexdigest()!=digest[7:]:raise ValueError('actual blob size/digest mismatch')
    return json.loads(raw,object_pairs_hook=unique_pairs)

