import gzip,hashlib,io,re,tarfile
from pathlib import Path
def read_layers(paths):
    out=[]
    for path in paths:
        raw=Path(path).read_bytes()
        with gzip.GzipFile(fileobj=io.BytesIO(raw)) as gz:data=gz.read(1048577)
        if len(data)>1048576:raise ValueError('teaching layer exceeds 1MiB')
        entries={}
        with tarfile.open(fileobj=io.BytesIO(data),mode='r:') as tar:
            for member in tar:
                name=member.name
                if not member.isfile() or not re.fullmatch(r'[A-Za-z0-9_.-]+',name) or name in ('.','..','.wh..wh..opq') or name in entries:raise ValueError('outside ordinary-file teaching subset')
                value=tar.extractfile(member).read()
                if name.startswith('.wh.') and (not name[4:] or value):raise ValueError('whiteout must be empty and name a target')
                entries[name]=value
        if any(name.startswith('.wh.') and name[4:] in entries for name in entries):raise ValueError('same-layer recreate not in this lesson')
        out.append((len(raw),entries))
    return out
def summarize(layer_bytes,visible):
    files=[{'name':name,'size':len(value),'sha256':hashlib.sha256(value).hexdigest()} for name,value in sorted(visible.items())]
