import base64,gzip,hashlib,json,re
from pathlib import Path
def load(root):
    root=Path(root);config=json.loads((root/'config.json').read_text());descriptors=json.loads((root/'layers.json').read_text());layers=[]
    for d in descriptors:
        if not re.fullmatch(r'layer-[0-9]+\.gz\.b64',d['file']):raise ValueError('invalid teaching layer path')
        compressed=base64.b64decode((root/d['file']).read_bytes(),validate=True)
        if len(compressed)!=d['size'] or 'sha256:'+hashlib.sha256(compressed).hexdigest()!=d['digest']:raise ValueError('compressed layer integrity mismatch')
        raw=gzip.decompress(compressed)
        if len(raw)>1024*1024:raise ValueError('teaching layer exceeds limit')
        layers.append((d['digest'],raw))
    return config,layers

