    def command(*args,allow_failure=False):
        result=subprocess.run(['openssl',*map(str,args)],cwd=root,capture_output=True,text=True,timeout=8)
        if result.returncode and not allow_failure:raise RuntimeError('certificate operation failed')
        return result
    prepared=[]
    # Prepare and validate all candidates before publishing any serving certificate.
    with tempfile.TemporaryDirectory(prefix='renewal-',dir=root) as directory:
        for target in config['targets']:
            cert=root/target['certificate']
            if command('x509','-in',cert,'-noout','-checkend','0',allow_failure=True).returncode==0:continue
            candidate=Path(directory)/(target['name']+'.crt')
