            command('verify','-CAfile',root/config['ca'],'-verify_ip',target['ip'],candidate)
            command('x509','-in',candidate,'-noout','-checkend','300')
            public_cert=command('x509','-in',candidate,'-pubkey','-noout').stdout
            public_key=command('pkey','-in',root/target['key'],'-pubout').stdout
            if public_cert!=public_key:raise RuntimeError('CSR does not match existing serving key')
            prepared.append((target['name'],candidate))
        for name,candidate in prepared:client.install(name,candidate)
        if not prepared:return {'renewed':[]}
        for dry_run in (True,False):
            if client.probe(True,dry_run)!=201:raise RuntimeError('approved operation still unavailable')
            if client.probe(False,dry_run)!=403:raise RuntimeError('business denial lost')
        return {'renewed':sorted(name for name,path in prepared)}
