import json,re

def validate_resource(resource):
    if not isinstance(resource,str) or not re.fullmatch(r'[a-z][a-z0-9-]{0,47}',resource):raise ValueError('invalid resource')

def grant(connect,resource):
    validate_resource(resource)
    conn=connect()
    try:
        row=conn.execute('INSERT INTO leases(resource,generation) VALUES(?,1) ON CONFLICT(resource) DO UPDATE SET generation=generation+1 RETURNING generation',(resource,)).fetchone()
        conn.commit()
        return {'resource':resource,'generation':row[0]}
    finally:conn.close()

def apply(connect,resource,token,value):
    validate_resource(resource)
    if not isinstance(token,dict) or set(token)!={'resource','generation'} or token['resource']!=resource or type(token['generation']) is not int or token['generation']<1:raise ValueError('invalid fencing token')
    if not isinstance(value,dict):raise ValueError('value must be a JSON object')
    encoded=json.dumps(value,ensure_ascii=False,allow_nan=False,separators=(',',':'))
    conn=connect()
    try:
        conn.execute('BEGIN IMMEDIATE')
        row=conn.execute('SELECT generation FROM leases WHERE resource=?',(resource,)).fetchone()
        if row is None or row[0]!=token['generation']:
            conn.rollback();return False
        conn.execute('INSERT INTO assets(resource,generation,value) VALUES(?,?,?) ON CONFLICT(resource) DO UPDATE SET generation=excluded.generation,value=excluded.value',(resource,token['generation'],encoded))
        conn.commit();return True
    except BaseException:
        conn.rollback();raise
    finally:conn.close()
